// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListInbox Unassigned spend grouped by session, for bulk triage
	// (GET /v1/inbox)
	ListInbox(w http.ResponseWriter, r *http.Request, params ListInboxParams)
	// GetMe Current user
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// LinkGitHub Link the Keycloak identity with a GitHub login
	// (PUT /v1/me/github-link)
	LinkGitHub(w http.ResponseWriter, r *http.Request)

	// (GET /v1/prices)
	ListPrices(w http.ResponseWriter, r *http.Request, params ListPricesParams)
	// CreatePrice Add a manual price override (admin)
	// (POST /v1/prices)
	CreatePrice(w http.ResponseWriter, r *http.Request)
	// SyncPrices Refresh seeded prices from models.dev (admin)
	// (POST /v1/prices/sync)
	SyncPrices(w http.ResponseWriter, r *http.Request)

	// (GET /v1/reports/costs)
	GetCostReport(w http.ResponseWriter, r *http.Request, params GetCostReportParams)

	// (GET /v1/repos)
	ListRepos(w http.ResponseWriter, r *http.Request)

	// (GET /v1/repos/{owner}/{repo})
	GetRepo(w http.ResponseWriter, r *http.Request, owner Owner, repo Repo)
	// SetStatusMap Override the detected Project status mapping (admin)
	// (PUT /v1/repos/{owner}/{repo}/status-map)
	SetStatusMap(w http.ResponseWriter, r *http.Request, owner Owner, repo Repo)

	// (GET /v1/tasks)
	ListTasks(w http.ResponseWriter, r *http.Request, params ListTasksParams)

	// (GET /v1/tasks/{owner}/{repo}/{number})
	GetTask(w http.ResponseWriter, r *http.Request, owner Owner, repo Repo, number Number)
	// RecordTaskPR Record the pull request and move the Project status to In Review
	// (POST /v1/tasks/{owner}/{repo}/{number}/pr)
	RecordTaskPR(w http.ResponseWriter, r *http.Request, owner Owner, repo Repo, number Number)
	// StartTask Record the start of work and move the Project status to In Progress
	// (POST /v1/tasks/{owner}/{repo}/{number}/start)
	StartTask(w http.ResponseWriter, r *http.Request, owner Owner, repo Repo, number Number)

	// (GET /v1/usage-events)
	ListUsageEvents(w http.ResponseWriter, r *http.Request, params ListUsageEventsParams)
	// IngestUsageEvents Ingest usage events captured by a daemon (idempotent)
	// (POST /v1/usage-events/batch)
	IngestUsageEvents(w http.ResponseWriter, r *http.Request)
	// ReassignUsageEvents Move events to an issue, or back to the inbox
	// (POST /v1/usage-events/reassign)
	ReassignUsageEvents(w http.ResponseWriter, r *http.Request)
	// RepriceUsageEvents Recompute costs with the current price book (admin)
	// (POST /v1/usage-events/reprice)
	RepriceUsageEvents(w http.ResponseWriter, r *http.Request)

	// (GET /v1/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
}

