// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/me/github-link", wrapper.LinkGitHub)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/usage-events/batch", wrapper.IngestUsageEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/usage-events", wrapper.ListUsageEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/usage-events/reassign", wrapper.ReassignUsageEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/usage-events/reprice", wrapper.RepriceUsageEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/inbox", wrapper.ListInbox)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tasks", wrapper.ListTasks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/tasks/{owner}/{repo}/{number}", wrapper.GetTask)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/tasks/{owner}/{repo}/{number}/start", wrapper.StartTask)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/tasks/{owner}/{repo}/{number}/pr", wrapper.RecordTaskPR)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/repos", wrapper.ListRepos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/repos/{owner}/{repo}", wrapper.GetRepo)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/repos/{owner}/{repo}/status-map", wrapper.SetStatusMap)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reports/costs", wrapper.GetCostReport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/prices", wrapper.ListPrices)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/prices", wrapper.CreatePrice)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/prices/sync", wrapper.SyncPrices)

	return m
}

