// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListInbox Unassigned spend grouped by session, for bulk triage
	// (GET /v1/inbox)
	ListInbox(ctx context.Context, request ListInboxRequestObject) (ListInboxResponseObject, error)
	// GetMe Current user
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// LinkGitHub Link the Keycloak identity with a GitHub login
	// (PUT /v1/me/github-link)
	LinkGitHub(ctx context.Context, request LinkGitHubRequestObject) (LinkGitHubResponseObject, error)

	// (GET /v1/prices)
	ListPrices(ctx context.Context, request ListPricesRequestObject) (ListPricesResponseObject, error)
	// CreatePrice Add a manual price override (admin)
	// (POST /v1/prices)
	CreatePrice(ctx context.Context, request CreatePriceRequestObject) (CreatePriceResponseObject, error)
	// SyncPrices Refresh seeded prices from models.dev (admin)
	// (POST /v1/prices/sync)
	SyncPrices(ctx context.Context, request SyncPricesRequestObject) (SyncPricesResponseObject, error)

	// (GET /v1/reports/costs)
	GetCostReport(ctx context.Context, request GetCostReportRequestObject) (GetCostReportResponseObject, error)

	// (GET /v1/repos)
	ListRepos(ctx context.Context, request ListReposRequestObject) (ListReposResponseObject, error)

	// (GET /v1/repos/{owner}/{repo})
	GetRepo(ctx context.Context, request GetRepoRequestObject) (GetRepoResponseObject, error)
	// SetStatusMap Override the detected Project status mapping (admin)
	// (PUT /v1/repos/{owner}/{repo}/status-map)
	SetStatusMap(ctx context.Context, request SetStatusMapRequestObject) (SetStatusMapResponseObject, error)

	// (GET /v1/tasks)
	ListTasks(ctx context.Context, request ListTasksRequestObject) (ListTasksResponseObject, error)

	// (GET /v1/tasks/{owner}/{repo}/{number})
	GetTask(ctx context.Context, request GetTaskRequestObject) (GetTaskResponseObject, error)
	// RecordTaskPR Record the pull request and move the Project status to In Review
	// (POST /v1/tasks/{owner}/{repo}/{number}/pr)
	RecordTaskPR(ctx context.Context, request RecordTaskPRRequestObject) (RecordTaskPRResponseObject, error)
	// StartTask Record the start of work and move the Project status to In Progress
	// (POST /v1/tasks/{owner}/{repo}/{number}/start)
	StartTask(ctx context.Context, request StartTaskRequestObject) (StartTaskResponseObject, error)

	// (GET /v1/usage-events)
	ListUsageEvents(ctx context.Context, request ListUsageEventsRequestObject) (ListUsageEventsResponseObject, error)
	// IngestUsageEvents Ingest usage events captured by a daemon (idempotent)
	// (POST /v1/usage-events/batch)
	IngestUsageEvents(ctx context.Context, request IngestUsageEventsRequestObject) (IngestUsageEventsResponseObject, error)
	// ReassignUsageEvents Move events to an issue, or back to the inbox
	// (POST /v1/usage-events/reassign)
	ReassignUsageEvents(ctx context.Context, request ReassignUsageEventsRequestObject) (ReassignUsageEventsResponseObject, error)
	// RepriceUsageEvents Recompute costs with the current price book (admin)
	// (POST /v1/usage-events/reprice)
	RepriceUsageEvents(ctx context.Context, request RepriceUsageEventsRequestObject) (RepriceUsageEventsResponseObject, error)

	// (GET /v1/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

